:root[data-theme="one-dark"] {
  --image-dark: #121214;
  --image-light: #ffffff;
  --theme-name: "One Dark";
  color-scheme: dark;

  /* surfaces, from the editor out to raised hover states */
  --background: #282c34; --sidebar: #21252b; --card: #21252b; --popover: #2c313a; --secondary: #3a3f4b; --muted: #2c313a; --sidebar-accent: #2c313a; --accent: #3a3f4b;
  /* text: primary, secondary, tertiary */
  --foreground: #abb2bf; --card-foreground: #abb2bf; --popover-foreground: #abb2bf; --secondary-foreground: #abb2bf; --accent-foreground: #abb2bf; --sidebar-foreground: #abb2bf; --sidebar-accent-foreground: #abb2bf; --muted-foreground: #9da5b4; --faint: #5c6370;
  /* borders and accent */
  --border: #181a1f; --input: #3a3f4b; --sidebar-border: #181a1f; --primary: #61afef; --ring: #61afef; --sidebar-primary: #61afef; --sidebar-ring: #61afef; --primary-text: #56b6c2; --primary-foreground: #282c34; --sidebar-primary-foreground: #282c34;
  /* selection, search matches, current line */
  --sel: #3e4451; --mark: rgba(229, 192, 123, 0.18); --mark-active: #d19a66; --cur: #2c313c;
  /* elevation */
  --shadow: 0 4px 16px rgba(0, 0, 0, 0.6);

  /* syntax */
  --k: #c678dd; --kt: #e5c07b; --nf: #61afef; --nc: #e5c07b; --nb: #56b6c2;
  --nv: #e06c75; --no: #d19a66; --na: #d19a66; --nt: #e06c75; --nd: #61afef;
  --np: #e06c75; --s: #98c379; --m: #d19a66; --o: #56b6c2; --p: #abb2bf;
  --c: #5c6370; --cp: #c678dd; --destructive: #e06c75; --err: #e06c75;

  /* diffs and status */
  --gi: #98c379; --gd: #e06c75;
  --gi-bg: rgba(152, 195, 121, 0.14); --gd-bg: rgba(224, 108, 117, 0.14);
}

